#!/bin/sh
# Scaffold for ho-config-nested-merge: writes the task's files into the current directory.
set -e
printf '"""Load app settings: built-in defaults overlaid with a user'\''s settings file.\n\n    python3 confload.py settings.json    print the merged settings\n    python3 confload.py --selfcheck      run the built-in cases (exit 1 on failure)\n"""\nimport json\nimport sys\n\nDEFAULTS = {\n    "port": 8080,\n    "logging": {"level": "info", "file": None},\n    "tags": [],\n}\n\n\ndef merge(base, override):\n    """Return base overlaid with override."""\n    merged = dict(base)\n    merged.update(override)\n    return merged\n\n\ndef load(path):\n    with open(path) as f:\n        return merge(DEFAULTS, json.load(f))\n\n\ndef selfcheck():\n    failures = []\n\n    def expect(name, got, want):\n        if got != want:\n            failures.append("{}: got {!r}, want {!r}".format(name, got, want))\n\n    expect("scalar override", merge({"port": 1}, {"port": 2}), {"port": 2})\n    expect(\n        "nested keys kept",\n        merge({"logging": {"level": "info", "file": None}}, {"logging": {"file": "a.log"}}),\n        {"logging": {"level": "info", "file": "a.log"}},\n    )\n    expect("lists are replaced, not joined", merge({"tags": ["a"]}, {"tags": ["b"]}), {"tags": ["b"]})\n    expect("new nested key added", merge({"a": 1}, {"b": {"c": 2}}), {"a": 1, "b": {"c": 2}})\n    merge(DEFAULTS, {"logging": {"file": "leak.log"}})\n    expect("defaults not modified", DEFAULTS["logging"], {"level": "info", "file": None})\n    for line in failures:\n        print("FAIL", line)\n    print("selfcheck: {} failed".format(len(failures)) if failures else "selfcheck: ok")\n    return 1 if failures else 0\n\n\nif __name__ == "__main__":\n    if sys.argv[1:] == ["--selfcheck"]:\n        sys.exit(selfcheck())\n    print(json.dumps(load(sys.argv[1]), indent=2))\n' > confload.py
